    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n == 1:
        return 0  # Handles edge case, though n=1 has no valid divisors
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return n // i
    return 1  # n is prime, largest divisor is 1

