def max_fill(grid, capacity):
    total = 0
    max_well_trips = 0
    for row in grid:
        well_water = sum(row)
        total += well_water
        if well_water == 0:
            continue
        # Calculate the number of trips needed for this well
        trips = (well_water + capacity - 1) // capacity
        if trips > max_well_trips:
            max_well_trips = trips
    # Calculate total trips based on total water
    total_trips = (total + capacity - 1) // capacity if total != 0 else 0
    return max(total_trips, max_well_trips)

